SELECT '==ARCHIVOS DE USUARIOS GRUPO 660 EN ACTIVIDADES DELETED ==' as '';
SELECT 'CROSS-REFERENCE: archivos subidos por usuarios del grupo 660 cuyo itemid es una actividad eliminada' AS info_;
SELECT 'DELETE_ASSIGNS con archivos de grupo 660:' AS info_;
SELECT f.id, f.itemid AS deleted_assign_id, u.id AS student_id, u.username AS cedula, u.firstname, u.lastname, f.filename, f.filesize, from_unixtime(f.timecreated) tc, a.name AS assign_name FROM isi_files f JOIN isi_user u ON u.id = f.userid JOIN isi_groups_members gm ON gm.userid = u.id AND gm.groupid = 660 LEFT JOIN isi_assign a ON a.id = f.itemid WHERE f.component = 'assignsubmission_file' AND f.filename <> '.' AND f.itemid IN (96, 97, 98, 99, 165, 257, 500, 65, 544, 735) ORDER BY f.itemid, u.id;
SELECT '==?El archivo de Leyda (itemid 735) esta en BD?==' as '';
SELECT 'Leyda (2758) todos sus archivos en assignsubmission_file curso 74:' AS info_;
SELECT f.id, f.itemid, f.filename, f.filesize, from_unixtime(f.timecreated) tc, f.contextid FROM isi_files f WHERE f.component = 'assignsubmission_file' AND f.filename <> '.' AND f.userid = 2758 AND f.contextid IN (SELECT id FROM isi_context WHERE contextlevel = 70 AND instanceid = 74) ORDER BY f.itemid;
SELECT '==ACTIVIDADES DONDE HAN SUBIDO ARCHIVOS ESTUDIANTES DEL GRUPO 660 EN ULTIMOS DIAS==' as '';
SELECT 'itemid, name, instance (assign_id), section, deleted_assign' AS info_;
SELECT DISTINCT cm.id AS cm_id, a.name AS activity_name, cm.instance AS assign_id, cm.section, s.name AS section_name, cm.deletioninprogress FROM isi_course_modules cm LEFT JOIN isi_assign a ON a.id = cm.instance LEFT JOIN isi_course_sections s ON s.id = cm.section WHERE cm.course = 74 AND cm.module = 1 AND cm.instance IN (SELECT DISTINCT f.itemid FROM isi_files f JOIN isi_groups_members gm ON gm.userid = f.userid AND gm.groupid = 660 WHERE f.component = 'assignsubmission_file' AND f.filename <> '.') ORDER BY cm.section, cm.instance;
